source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {value for row in grid for value in row if value}
    frames = []
    frame_colors = set()

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) < 8:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        perimeter = 2 * (r1 - r0 + 1) + 2 * (c1 - c0 + 1) - 4
        if len(cells) != perimeter or r1 - r0 < 2 or c1 - c0 < 2:
            continue

        is_frame = True
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                edge = r in (r0, r1) or c in (c0, c1)
                if (edge and grid[r][c] != color) or (not edge and grid[r][c] != 0):
                    is_frame = False
        if is_frame:
            frames.append((color, r0, r1, c0, c1))
            frame_colors.add(color)

    marker_counts = Counter(
        value for row in grid for value in row if value and value not in frame_colors
    )
    output = [[value if value in frame_colors else 0 for value in row] for row in grid]

    for _, r0, r1, c0, c1 in frames:
        ir0, ir1, ic0, ic1 = r0 + 1, r1 - 1, c0 + 1, c1 - 1
        parity = (ir0 + ic0) % 2
        needed = sum(
            (r + c) % 2 == parity
            for r in range(ir0, ir1 + 1)
            for c in range(ic0, ic1 + 1)
        )
        fill_color = next(
            (color for color, count in marker_counts.items() if count == needed), None
        )
        if fill_color is not None:
            for r in range(ir0, ir1 + 1):
                for c in range(ic0, ic1 + 1):
                    if (r + c) % 2 == parity:
                        output[r][c] = fill_color

    return output
'''
